/**
 * F145 — static crawl of public internal navigation generated by Astro.
 * Unlike the sitemap, links must form a navigable graph from the home page.
 * The route list is supplied by the curated site catalog, no HTTP is used.
 */
import assert from 'node:assert/strict';
import {anchorOpeningTags,requiredAnchorHref} from './html-anchor-reader.mjs';

const ROUTE=/^\/(?:[a-z0-9-]+\/)*$/;

export function auditPublicLinkGraph(pages,{maxClicks=3}={}){
  assert.ok(Array.isArray(pages)&&pages.length>=2,
    'F145: complete compiled site graph required');
  assert.ok(Number.isSafeInteger(maxClicks)&&maxClicks>=1&&maxClicks<=8,
    'F145: bounded graph depth required');
  const map=new Map();
  for(const page of pages){
    assert.ok(page&&typeof page.path==='string'&&
      typeof page.html==='string','F145: invalid generated page');
    assert.match(page.path,ROUTE,'F145: invalid public page path');
    assert.ok(!map.has(page.path),'F145: repeated public route');
    map.set(page.path,page.html);
  }
  assert.ok(map.has('/'),'F145: home route required');
  const neighbors=new Map();
  for(const [path,html] of map){
    const links=new Set();
    for(const tag of anchorOpeningTags(html)){
      const href=requiredAnchorHref(tag);
      if(typeof href!=='string'||!href.startsWith('/')||
        href.startsWith('//'))continue;
      const dest=href.split('#',1)[0];
      if(map.has(dest))links.add(dest);
    }
    neighbors.set(path,links);
  }
  const depth=new Map([['/',0]]);
  const queue=['/'];
  for(let i=0;i<queue.length;i++){
    const current=queue[i],dist=depth.get(current);
    for(const dest of neighbors.get(current)){
      if(!depth.has(dest)){
        depth.set(dest,dist+1);
        queue.push(dest);
      }
    }
  }
  assert.equal(depth.size,map.size,
    'F145: orphan public pages are not reachable from home');
  const furthest=Math.max(...depth.values());
  assert.ok(furthest<=maxClicks,
    'F145: public page requires too many navigation steps');
  return Object.freeze({
    publicPages:map.size,
    reachablePages:depth.size,
    maxClicksFromHome:furthest,
    networkPerformed:false
  });
}
